// Precomputed territory areas, with a guard and a fallback.
//
// calculatePathAreas() samples 80 points along each of the 359 territory paths with
// getPointAtLength() and applies the shoelace formula -- about 230ms of main-thread
// work on every page load, for an answer that only changes when the SVG does.
// See docs/01-codebase-audit.md section 4.2.
//
// resources/pathAreas.json is generated by tools/precompute-areas.mjs, which runs
// the identical algorithm in headless Chromium so the cached values cannot drift
// from the live implementation.
//
// GUARD
//
// Stale precomputed geometry would be worse than slow geometry: every territory's
// resource yields and its defensive area bonus derive from `area`. Before the cache
// is used it is checked against the live SVG on three counts -- byte size, path
// count, and every live uniqueId being present. Any mismatch returns null and the
// caller recomputes, so an edited map degrades to "slow but correct", never to
// "fast but wrong".
//
// This module imports nothing.

const PATH_AREAS_URL = "./resources/pathAreas.json";

/** @type {{svgBytes:number, pathCount:number, areas:Array}|null} */
let data = null;

/** @type {Promise<object|null>|null} */
let loadPromise = null;

/**
 * Fetch the precomputed areas. Resolves to null rather than rejecting when the file
 * is absent or unreadable: a missing cache is not an error, it just means the
 * caller computes the areas itself.
 *
 * @param {object}   [options]
 * @param {string}   [options.url]
 * @param {Function} [options.fetchImpl]
 * @returns {Promise<object|null>}
 */
export function loadPrecomputedPathAreas({ url = PATH_AREAS_URL, fetchImpl } = {}) {
    if (loadPromise) {
        return loadPromise;
    }

    const doFetch = fetchImpl ?? globalThis.fetch;

    loadPromise = Promise.resolve()
        .then(() => doFetch(url))
        .then((response) => {
            if (!response || response.ok === false) {
                return null;
            }
            return response.json();
        })
        .then((parsed) => {
            data = parsed && Array.isArray(parsed.areas) ? parsed : null;
            return data;
        })
        .catch(() => {
            data = null;
            return null;
        });

    return loadPromise;
}

/**
 * The precomputed areas, if and only if they still describe the live SVG.
 *
 * @param {ArrayLike<{getAttribute:Function}>} paths  the live territory paths
 * @param {number} svgBytes  byte length of the SVG the page actually loaded
 * @returns {Array|null}  a fresh array of area records, or null to recompute
 */
export function precomputedAreasFor(paths, svgBytes) {
    if (!data) {
        return null;
    }
    if (data.svgBytes !== svgBytes) {
        return null;
    }
    if (data.pathCount !== paths.length) {
        return null;
    }

    const byId = new Map(data.areas.map((entry) => [String(entry.uniqueId), entry]));
    for (const path of paths) {
        if (!byId.has(String(path.getAttribute("uniqueid")))) {
            return null;
        }
    }

    return data.areas.map((entry) => ({ ...entry }));
}

/** Test seam. */
export function __resetPathAreasForTests() {
    data = null;
    loadPromise = null;
}
